 "content": "from collections import Counter, deque


def components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            result.append((color, cells))
    return bg, result


def signature(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)


def l_box(cells):
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    if r1-r0 < 2 or c1-c0 < 2:
        return None
    corners = ((r0, c0, 'tl'), (r0, c1, 'tr'),
               (r1, c0, 'bl'), (r1, c1, 'br'))
    for r, c, _ in corners:
        if (all((r, x) in cells for x in range(c0, c1+1)) and
                all((y, c) in cells for y in range(r0, r1+1))):
            return r0, r1, c0, c1
    return None


def transform(grid):
    _, objs = components(grid)
    out = [row[:] for row in grid]
    frames = []
    for i, (color, cells) in enumerate(objs):
        box = l_box(cells)
        if box is not None:
            frames.append((len(cells), i, color, cells, box))
    if not frames:
        return out
    _, frame_i, frame_color, frame, (r0, r1, c0, c1) = max(frames)
    inside_shapes = set()
    for i, (_, cells) in enumerate(objs):
        if i != frame_i and all(r0 <= r <= r1 and c0 <= c <= c1
                                for r, c in cells):
            inside_shapes.add(signature(cells))
    for i, (_, cells) in enumerate(objs):
        if i == frame_i:
            continue
        is_outside = any(r < r0 or r > r1 or c < c0 or c > c1
                         for r, c in cells)
        if is_outside and signature(cells) in inside_shapes:
            for r, c in cells:
                out[r][c] = frame_color
    return out


if __name__ == '__main__':
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
