            result.append((color, cells))
    return bg, result


def signature(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)


def transform(grid):
    _, objs = components(grid)
    out = [row[:] for row in grid]
    proposals = []
    for i, (marker, frame) in enumerate(objs):
        r0 = min(r for r, c in frame)
        r1 = max(r for r, c in frame)
        c0 = min(c for r, c in frame)
        c1 = max(c for r, c in frame)
        h, w = r1-r0+1, c1-c0+1
        if h < 3 or w < 3 or len(frame)/(h*w) > 0.65:
            continue
        l_corner = None
        for hr, vc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            if (all((hr,c) in frame for c in range(c0,c1+1)) and
                    all((r,vc) in frame for r in range(r0,r1+1))):
                l_corner = (hr, vc)
                break
        if l_corner is None:
            continue
        hr, vc = l_corner
        for j, (color, cells) in enumerate(objs):
            if j == i:
                continue
