    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    return frozenset((r-r0,c-c0) for r,c in cells)


def transform(grid):
    _,objs=components(grid); out=[row[:] for row in grid]
    frames=[]
    for i,(color,cells) in enumerate(objs):
        r0=min(r for r,c in cells); r1=max(r for r,c in cells)
        c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        h=r1-r0+1; w=c1-c0+1
        if h<3 or w<3 or len(cells)/(h*w)>0.65: continue
        corners=[]
        for hr,vc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            if all((hr,c) in cells for c in range(c0,c1+1)) and all((r,vc) in cells for r in range(r0,r1+1)):
                corners.append((hr,vc))
        if corners:
            # At least one other object occupies the bounded open area behind this L.
            cavity=[(j,col,obj) for j,(col,obj) in enumerate(objs) if j!=i and all(r0<=r<=r1 and c0<=c<=c1 for r,c in obj)]
            if cavity:
