    if not frames: return out
    _,fi,marker,(r0,r1,c0,c1),inner=max(frames,key=lambda x:(x[0],len(x[4])))
    # Only recolor an object whose exact translated shape is represented by an
    # object inside the L's bounding rectangle, and which lies outside it.
    shapes={norm(obj) for j,_,obj in inner if j!=fi}
    targets=[]
    for j,(col,obj) in enumerate(objs):
        if j==fi: continue
        outside=any(not (r0<=r<=r1 and c0<=c<=c1) for r,c in obj)
        if outside and norm(obj) in shapes:
            targets.append(obj)
    if targets:
        for obj in targets:
            for r,c in obj: out[r][c]=marker
    else:
        # In some examples the L identifies an inside component's color; recolor
        # the outside component of that color, independent of its shape.
        colors={col for j,col,obj in inner if j!=fi}
        for j,(col,obj) in enumerate(objs):
            if j!=fi and col in colors and any(not (r0<=r<=r1 and c0<=c<=c1) for r,c in obj):
