 "content": "from collections import Counter, deque


def components(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            seen.add((r,c)); q=deque([(r,c)]); cells=set()
            while q:
                y,x=q.popleft(); cells.add((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if (0<=yy<h and 0<=xx<w and (yy,xx) not in seen
                            and grid[yy][xx]==color):
                        seen.add((yy,xx)); q.append((yy,xx))
            objects.append((color,cells))
    return bg,objects


def transform(grid):
    bg, objects = components(grid)
    out=[row[:] for row in grid]
    # Find a sparse L-shaped marker: two complete perpendicular bbox edges,
    # with its corner at one endpoint of both arms.
    frames=[]
    for i,(color,cells) in enumerate(objects):
        r0=min(r for r,c in cells); r1=max(r for r,c in cells)
        c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        h=r1-r0+1; w=c1-c0+1
        if h<3 or w<3 or len(cells)/(h*w)>.65:
            continue
        for hr,vc in ((r0,c0),(r0,c1),(r1,c0),(r1,c1)):
            if (all((hr,c) in cells for c in range(c0,c1+1)) and
                all((r,vc) in cells for r in range(r0,r1+1))):
                inside=[(j,col,obj) for j,(col,obj) in enumerate(objects)
                        if j!=i and all(r0<=r<=r1 and c0<=c<=c1 for r,c in obj)]
                if inside:
                    frames.append((len(cells),i,color,(r0,r1,c0,c1),inside))
                break
    if not frames:
        return out
    _,fi,marker,(r0,r1,c0,c1),inside=max(frames,key=lambda x:(x[0],len(x[4])))
    inner_colors={col for j,col,obj in inside}
    # Recolor exterior objects sharing a color with an object inside the marker.
    # In demos where shapes rather than colors identify counterparts, use exact
    # translation-normalized component shape as the fallback.
    targets=[]
    for j,(col,obj) in enumerate(objects):
        outside=any(not (r0<=r<=r1 and c0<=c<=c1) for r,c in obj)
        if j!=fi and outside and col in inner_colors:
            targets.append(obj)
    if not targets:
        def norm(cells):
            a=min(r for r,c in cells); b=min(c for r,c in cells)
            return frozenset((r-a,c-b) for r,c in cells)
        shapes={norm(obj) for j,col,obj in inside}
        targets=[obj for j,(col,obj) in enumerate(objects) if j!=fi and
                 any(not (r0<=r<=r1 and c0<=c<=c1) for r,c in obj) and
                 norm(obj) in shapes]
    for obj in targets:
        for r,c in obj:
            out[r][c]=marker
    return out


if __name__ == '__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
